function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 10000) return 'k is an integer from 1 to 10000.';
  return null;
}

