function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const alphabet = size === 'large' || rand() < 0.5 ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[Math.floor(rand() * alphabet.length)];
  const k = size === 'large' || rand() < 0.3 ? 1 + Math.floor(rand() * 10000) : 1 + Math.floor(rand() * 15);
  return [s, k];
}
